<?php
session_start();
if(!isset($_SESSION['usuario_id'])||!in_array($_SESSION['rol']??'', ['administrador','empleado'],true)){http_response_code(403);exit('Acceso denegado');}
$isAdmin=($_SESSION['rol']==='administrador');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cuentas · Azucreativo</title><style>body{font:16px system-ui;background:#edf5ff;color:#18345b;margin:0}main{max-width:920px;margin:35px auto;padding:24px;background:white;border-radius:15px}label{display:block;margin:10px 0}input,select,button{padding:10px;margin:3px;border:1px solid #b3c8e8;border-radius:7px}button{background:#1758a8;color:white;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}#mensaje{white-space:pre-wrap}small{color:#555}</style><link rel="stylesheet" href="/Azucreativo/config/avisos-legibles.css?v=20261122">

<link rel="stylesheet" href="/Azucreativo/config/mobile-responsive.css?v=20261122logout2">
<script src="/Azucreativo/config/mobile-responsive.js?v=20261122" defer></script>
</head><body><main><a href="<?= $isAdmin?'../index.php':'../empleado/index.php' ?>">← Volver</a><h1>Administración de cuentas</h1><p><?= $isAdmin?'Administrador: gestiona clientes, empleados y otros administradores.':'Empleado: puedes registrar clientes con autorización administrativa.' ?></p>
<?php if($isAdmin): ?><section><h2>Clave de autorización personal (15 días)</h2><p>Configura una clave distinta a la contraseña de inicio de sesión. Cuando venza, debes establecer otra con tu contraseña de acceso.</p><label>Contraseña de acceso actual <input id="password_actual" type="password" autocomplete="current-password"></label><label>Nueva clave de autorización (4 dígitos) <input id="nueva_clave" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="new-password"></label><button id="renovar">Establecer o renovar clave</button><p id="vigencia"></p></section><?php endif; ?>
<hr><section><h2>Crear / modificar cuenta</h2><form id="cuenta"><input type="hidden" name="id" id="id"><label>Usuario <input name="usuario" required maxlength="50"></label><label>Correo <input name="correo" type="email" required></label><label>Contraseña <input name="password" type="password" placeholder="Nueva contraseña (opcional al editar)"></label><label>Rol <select name="rol" id="rol"><option value="cliente">Cliente</option><?php if($isAdmin): ?><option value="empleado">Empleado</option><option value="administrador">Administrador</option><?php endif; ?></select></label><p><small>Identificadores automáticos: EMP-00001 (empleado), CLI-00001 (cliente) y ADM-00001 (administrador). Cada rol conserva su ID interno independiente.</small></p><label>Nombre (cliente o empleado) <input name="nombre"></label><label>Apellido (cliente o empleado) <input name="apellido"></label><fieldset><legend>Autorización requerida</legend><label>ID del administrador que autoriza <input name="admin_autorizador" type="number" min="1" value="<?= $isAdmin?(int)$_SESSION['usuario_id']:'' ?>" required></label><label>Clave de autorización <input name="clave_autorizacion" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required></label></fieldset><button>Guardar cuenta</button><button type="reset" id="limpiar">Limpiar</button></form></section><p id="mensaje" role="status"></p>
<?php if($isAdmin): ?><section><h2>Cuentas existentes</h2><small>Eliminar perfil borra definitivamente la cuenta y sus datos de perfil. Conserva las ventas históricas anonimizadas. Esta acción no se puede deshacer. Haz un respaldo antes de usarla.</small><table><thead><tr><th>Identificador</th><th>ID acceso</th><th>Usuario</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="lista"></tbody></table></section><?php endif; ?></main><script>
const $=x=>document.getElementById(x),admin=<?= $isAdmin?'true':'false' ?>;let cuentas=[];
async function req(data){const r=await fetch('usuarios_api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.mensaje||'Error');return j}
function mensaje(s){$('mensaje').textContent=s}
async function listar(){if(!admin)return;try{cuentas=(await req({accion:'listar'})).datos;const tb=$('lista');tb.replaceChildren();for(const c of cuentas){const tr=document.createElement('tr');for(const val of [c.identificador||'Sin vincular',c.id,c.usuario,c.correo,c.rol,c.activo?'Activa':'Inactiva']){const td=document.createElement('td');td.textContent=val;tr.append(td)}const td=document.createElement('td');const b=document.createElement('button');b.textContent='Editar';b.onclick=()=>{for(const k of ['id','usuario','correo','rol'])$('cuenta').elements[k].value=c[k];$('cuenta').elements.password.value='';window.scrollTo(0,0)};td.append(b);const del=document.createElement('button');del.textContent=c.activo?'Desactivar':'Reactivar';del.onclick=async()=>{const clave=prompt('Clave de autorización del administrador');if(clave===null)return;try{await req({accion:'estado',id:c.id,activo:c.activo?0:1,clave_autorizacion:clave});await listar();mensaje('Estado actualizado')}catch(e){mensaje(e.message)}};td.append(del);if(Number(c.id)!==Number(<?= (int)$_SESSION['usuario_id'] ?>)){const quitar=document.createElement('button');quitar.type='button';quitar.textContent='Eliminar perfil';quitar.style.background='#a52840';quitar.onclick=async()=>{if(!confirm('¿ELIMINAR DEFINITIVAMENTE el perfil '+c.usuario+' ('+c.identificador+')? Se conservarán las ventas históricas anonimizadas. Esta acción no se puede deshacer.'))return;const clave=prompt('Introduce tu clave de autorización de 4 dígitos');if(clave===null)return;try{const r=await req({accion:'eliminar',id:c.id,confirmacion:'ELIMINAR',admin_autorizador:<?= (int)$_SESSION['usuario_id'] ?>,clave_autorizacion:clave});await listar();mensaje(r.mensaje)}catch(e){mensaje(e.message)}};td.append(quitar)}tr.append(td);tb.append(tr)}}catch(e){mensaje(e.message)}}
$('cuenta').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.accion='guardar';try{const r=await req(d);mensaje(r.mensaje);window.alert(r.mensaje);e.target.reset();$('id').value='';await listar()}catch(e){mensaje(e.message)}};
if(admin){$('renovar').onclick=async()=>{try{const r=await req({accion:'renovar',password_actual:$('password_actual').value,nueva_clave:$('nueva_clave').value});$('password_actual').value='';$('nueva_clave').value='';$('vigencia').textContent=r.mensaje;mensaje(r.mensaje);window.alert(r.mensaje)}catch(e){mensaje(e.message)}};listar()}
</script></body></html>